(6047022, 889071, 108982, '<td valign="top">another genesee river falls picture.  Look me up after voting I''m from the area.  nice shot BTW</td>', 'another genesee river falls picture.  Look me up after voting I''m from the area.  nice shot BTW', '2010-06-08 19:53:17.000000', NULL, 1),
(6047030, 887973, 108982, '<td valign="top">I like the girl.  I like the building.  I''m not sure I like the combination with no real emphasis on either.  There is a lot going on in the building itself, it really doesn''t "need" the girl and vice versa...</td>', 'I like the girl.  I like the building.  I''m not sure I like the combination with no real emphasis on either.  There is a lot going on in the building itself, it really doesn''t "need" the girl and vice versa...', '2010-06-08 19:57:53.000000', NULL, 1),
