(6047058, 889017, 118409, '<td valign="top">AAAAAAAAW, cute train</td>', 'AAAAAAAAW, cute train', '2010-06-08 20:24:21.000000', NULL, 1),
(6047059, 888989, 108982, '<td valign="top">I was at a car dealership today and there was a photo of an old toy truck set against a bunch of plants so as to look like trees and give the toy a feel of a large vehicle.  I thought to myself, "what a cool Idea for the HDR?  I have some old toy trucks at home (these two to be exact) but I had already submitted and the time had passed.  How coincidental that this is here  and what a nice job you did...the spirit of an HDR is here,great color, detail and subject.  My top pick...TEN  after all it was my idea...wink.</td>', 'I was at a car dealership today and there was a photo of an old toy truck set against a bunch of plants so as to look like trees and give the toy a feel of a large vehicle.  I thought to myself, "what a cool Idea for the HDR?  I have some old toy trucks at home (these two to be exact) but I had already submitted and the time had passed.  How coincidental that this is here  and what a nice job you did...the spirit of an HDR is here,great color, detail and subject.  My top pick...TEN  after all it was my idea...wink.', '2010-06-08 20:26:24.000000', NULL, 1),
(6047060, 888326, 108982, '<td valign="top">beautiful</td>', 'beautiful', '2010-06-08 20:26:42.000000', NULL, 1),
(6047062, 888282, 108982, '<td valign="top">A Molson anyone?</td>', 'A Molson anyone?', '2010-06-08 20:28:38.000000', NULL, 1),
(6047073, 888957, 23484, '<td valign="top">Beautiful shot and good job at not overdoing it.</td>', 'Beautiful shot and good job at not overdoing it.', '2010-06-08 20:41:06.000000', NULL, 1);
