(6047080, 889049, 23484, '<td valign="top">I like the clouds. Nice job.</td>', 'I like the clouds. Nice job.', '2010-06-08 20:43:46.000000', NULL, 1),
(6047081, 888053, 23484, '<td valign="top">Now this is very ominous looking. Great shot.</td>', 'Now this is very ominous looking. Great shot.', '2010-06-08 20:44:16.000000', NULL, 1),
(6047083, 888282, 23484, '<td valign="top">The HDR really makes this pop.</td>', 'The HDR really makes this pop.', '2010-06-08 20:44:41.000000', NULL, 1),
(6047085, 888967, 23484, '<td valign="top">Excellent job without over doing the HDR.</td>', 'Excellent job without over doing the HDR.', '2010-06-08 20:45:37.000000', NULL, 1),
