(6048065, 888968, 86359, '<td valign="top">I think that this would do much better as a B&amp;W image because some colors are very unnatural</td>', 'I think that this would do much better as a B&W image because some colors are very unnatural', '2010-06-09 09:53:00.000000', NULL, 1),
(6048121, 888762, 84363, '<td valign="top">Photo looks very pixelated and distorted.  May have been over-sharpened?</td>', 'Photo looks very pixelated and distorted.  May have been over-sharpened?', '2010-06-09 10:31:41.000000', NULL, 1),
(6048129, 888241, 84363, '<td valign="top">HDR is intended to pull out more tonal range from a photo, not blow out the highlights and distort the color.</td>', 'HDR is intended to pull out more tonal range from a photo, not blow out the highlights and distort the color.', '2010-06-09 10:35:00.000000', NULL, 1),
(6048133, 888283, 84363, '<td valign="top">Nice!  Really like the photo.  Overall it seems just a tad to dark.  Have you tried bumping up the mid-tones just a bit?  Or maybe a bit more saturation (HDR) on the wall?</td>', 'Nice!  Really like the photo.  Overall it seems just a tad to dark.  Have you tried bumping up the mid-tones just a bit?  Or maybe a bit more saturation (HDR) on the wall?', '2010-06-09 10:37:16.000000', NULL, 1),
(6048139, 888307, 84363, '<td valign="top">Galaxies or roadkill...whichever....<br/>Not really sure how this fits into HDR.  HDR is meant to pull out more tonal range than you would typically have in a photo.  Not sure this does that.</td>', 'Galaxies or roadkill...whichever....Not really sure how this fits into HDR.  HDR is meant to pull out more tonal range than you would typically have in a photo.  Not sure this does that.', '2010-06-09 10:39:07.000000', NULL, 1),
(6048143, 888995, 84363, '<td valign="top">My eye just kinda wonders...  Nothing really to pull my eye in.</td>', 'My eye just kinda wonders...  Nothing really to pull my eye in.', '2010-06-09 10:40:12.000000', NULL, 1),
(6048147, 889092, 84363, '<td valign="top">Why so much pixelation and distortion?  Without that this would proably be a really good photo!  I can see how the HDR would have worked especially on the grass.</td>', 'Why so much pixelation and distortion?  Without that this would proably be a really good photo!  I can see how the HDR would have worked especially on the grass.', '2010-06-09 10:41:55.000000', NULL, 1),
