(6048153, 889253, 84363, '<td valign="top">The colors are blown out and blochy...not what HDR is supposed to do.</td>', 'The colors are blown out and blochy...not what HDR is supposed to do.', '2010-06-09 10:44:02.000000', NULL, 1),
