(6049403, 888176, 106349, '<td valign="top">Like it except for the halos al.round the barn</td>', 'Like it except for the halos al.round the barn', '2010-06-09 22:21:18.000000', NULL, 1),
(6049415, 888286, 57447, '<td valign="top">Pretty location, nice detail and composition.</td>', 'Pretty location, nice detail and composition.', '2010-06-09 22:40:24.000000', NULL, 1),
(6049449, 889240, 69246, '<td valign="top">Good balance of light between the white crests and the rocks. It could use a little more adjustments in the shadows though.</td>', 'Good balance of light between the white crests and the rocks. It could use a little more adjustments in the shadows though.', '2010-06-09 23:12:25.000000', NULL, 1),
(6049451, 888980, 69246, '<td valign="top">Good attempt at the style. But there is a high degree of haloing around the top of the church.</td>', 'Good attempt at the style. But there is a high degree of haloing around the top of the church.', '2010-06-09 23:13:48.000000', NULL, 1),
(6049509, 889073, 82999, '<td valign="top">Wonderful.  Just excellent.</td>', 'Wonderful.  Just excellent.', '2010-06-10 00:18:54.000000', NULL, 1),
(6049511, 888201, 82999, '<td valign="top">Superb.  Truly excellent.</td>', 'Superb.  Truly excellent.', '2010-06-10 00:19:20.000000', NULL, 1),
(6049545, 889068, 40718, '<td valign="top">I really like this one.  Would like to see it Top 10, but I''m not sure I have faith in DPC for that...</td>', 'I really like this one.  Would like to see it Top 10, but I''m not sure I have faith in DPC for that...', '2010-06-10 00:41:53.000000', NULL, 1),
(6049548, 887333, 40718, '<td valign="top">A little too much highlight in the clouds for me Jeb, but I love the subject. (no vote)</td>', 'A little too much highlight in the clouds for me Jeb, but I love the subject. (no vote)', '2010-06-10 00:45:44.000000', NULL, 1),
(6049576, 889037, 98022, '<td valign="top">Awesome sky! Great job - 9</td>', 'Awesome sky! Great job - 9', '2010-06-10 01:24:24.000000', NULL, 1),
(6049694, 889277, 79955, '<td valign="top">interesting , very painterly look &amp; feel to the image. nice , 7</td>', 'interesting , very painterly look & feel to the image. nice , 7', '2010-06-10 05:23:26.000000', NULL, 1),
(6049695, 889012, 79955, '<td valign="top">No vote !! , Lovely capture and good luck.</td>', 'No vote !! , Lovely capture and good luck.', '2010-06-10 05:23:34.000000', NULL, 1),
(6049696, 889258, 79955, '<td valign="top">I like the lighting, nice crisp image with lots of details. 7</td>', 'I like the lighting, nice crisp image with lots of details. 7', '2010-06-10 05:24:38.000000', NULL, 1),
(6049698, 888926, 79955, '<td valign="top">A little overdone , but nice contrast.<strike>6</strike> LOL , when I thought I had finished looking at the image &amp; had moved to the next image , I realized I missed the sun rays &amp; the person on the left. <br/> <br/>Well with the new interesting subjects in the image , I would recommend a tighter crop (crop away the sand at the bottom of the image) 7</td>', 'A little overdone , but nice contrast.6 LOL , when I thought I had finished looking at the image & had moved to the next image , I realized I missed the sun rays & the person on the left.  Well with the new interesting subjects in the image , I would recommend a tighter crop (crop away the sand at the bottom of the image) 7', '2010-06-10 05:29:25.000000', NULL, 1),
