(6052616, 888282, 106974, '<td valign="top">There is a problem here. It is day time and sky is black as night. There are no details in the trees on the left and the hill on the right. It''s weak for a hdr concept. Details details more details.</td>', 'There is a problem here. It is day time and sky is black as night. There are no details in the trees on the left and the hill on the right. It''s weak for a hdr concept. Details details more details.', '2010-06-12 16:39:29.000000', NULL, 1),
(6052622, 889194, 106974, '<td valign="top">The green parts are still too dark. Incomplete HDR :)</td>', 'The green parts are still too dark. Incomplete HDR :)', '2010-06-12 16:44:54.000000', NULL, 1),
(6052624, 888369, 106974, '<td valign="top">Wooow and could be better. The grey hills look dull. Need some contrast maybe?</td>', 'Wooow and could be better. The grey hills look dull. Need some contrast maybe?', '2010-06-12 16:46:09.000000', NULL, 1),
(6052630, 888980, 106974, '<td valign="top">A bit over tone mapped for my eyes. Too sharp and contrasted. And it is a good shut still.</td>', 'A bit over tone mapped for my eyes. Too sharp and contrasted. And it is a good shut still.', '2010-06-12 16:48:24.000000', NULL, 1),
(6052632, 888933, 106974, '<td valign="top">Very nice balanced. Not overtoned not too dark. I see every detail. Good work.</td>', 'Very nice balanced. Not overtoned not too dark. I see every detail. Good work.', '2010-06-12 16:49:26.000000', NULL, 1),
(6052634, 888919, 106974, '<td valign="top">May the force be with you. After few beers, a jedi knight sees his light saber like wine sabers :)</td>', 'May the force be with you. After few beers, a jedi knight sees his light saber like wine sabers :)', '2010-06-12 16:51:16.000000', NULL, 1),
(6052635, 889206, 106974, '<td valign="top">It looks like a video game render :)</td>', 'It looks like a video game render :)', '2010-06-12 16:52:23.000000', NULL, 1),
(6052637, 888794, 106974, '<td valign="top">Background is black. Cant see any detail. This can be a MDR :)</td>', 'Background is black. Cant see any detail. This can be a MDR :)', '2010-06-12 16:56:03.000000', NULL, 1),
(6052644, 888307, 106974, '<td valign="top">Is that misalignment or did you do it ? And this is looks like a rat corpse rather than a galaxy.</td>', 'Is that misalignment or did you do it ? And this is looks like a rat corpse rather than a galaxy.', '2010-06-12 17:05:06.000000', NULL, 1),
(6052747, 888961, 109962, '<td valign="top">I love this picture! I''m always trying to shoot the sun through something and it never turns out this well. Awesome!</td>', 'I love this picture! I''m always trying to shoot the sun through something and it never turns out this well. Awesome!', '2010-06-12 19:31:29.000000', NULL, 1),
(6052772, 889279, 118480, '<td valign="top">Great Shot love this one</td>', 'Great Shot love this one', '2010-06-12 19:49:43.000000', NULL, 1),
(6052773, 887550, 118480, '<td valign="top">awesome shot, great colours and use of angles</td>', 'awesome shot, great colours and use of angles', '2010-06-12 19:50:46.000000', NULL, 1),
(6052775, 887876, 118480, '<td valign="top">great work, looks like a painting</td>', 'great work, looks like a painting', '2010-06-12 19:53:14.000000', NULL, 1),
(6052777, 889244, 118480, '<td valign="top">Amazing work great use of the technique</td>', 'Amazing work great use of the technique', '2010-06-12 19:55:54.000000', NULL, 1),
(6052817, 889037, 17507, '<td valign="top">This is just plain killer. This is what landscape photography is about.</td>', 'This is just plain killer. This is what landscape photography is about.', '2010-06-12 21:18:43.000000', NULL, 1),
(6052818, 889194, 17507, '<td valign="top">Gentle, peaceful, deep, crisp, clear; as eloquent as imagery can be.</td>', 'Gentle, peaceful, deep, crisp, clear; as eloquent as imagery can be.', '2010-06-12 21:19:07.000000', NULL, 1),
(6052820, 889274, 17507, '<td valign="top">Great title. Great picture. Sharp and clear, strong composition, great tones and colors.</td>', 'Great title. Great picture. Sharp and clear, strong composition, great tones and colors.', '2010-06-12 21:19:38.000000', NULL, 1),
(6052822, 888190, 17507, '<td valign="top">Different. Thought-provoking. Real. I very much like.</td>', 'Different. Thought-provoking. Real. I very much like.', '2010-06-12 21:19:53.000000', NULL, 1),
(6052874, 888176, 66515, '<td valign="top">some unfortunate haloing from the processing really takes away from a potentially great scene</td>', 'some unfortunate haloing from the processing really takes away from a potentially great scene', '2010-06-12 22:02:40.000000', NULL, 1),
(6052876, 888110, 66515, '<td valign="top">Really would have like to see this submitted with the full size allowed (800 px wide on the longest edge). You''re really cheating yourself of letting the viewer get the full impact with the smaller image.</td>', 'Really would have like to see this submitted with the full size allowed (800 px wide on the longest edge). You''re really cheating yourself of letting the viewer get the full impact with the smaller image.', '2010-06-12 22:05:53.000000', NULL, 1),
(6052888, 889192, 66515, '<td valign="top">ouch...nasty haloing going on here.</td>', 'ouch...nasty haloing going on here.', '2010-06-12 22:13:38.000000', NULL, 1),
(6052897, 888926, 66515, '<td valign="top">really over sharpened. Too bad because this scene has lots of potential</td>', 'really over sharpened. Too bad because this scene has lots of potential', '2010-06-12 22:27:53.000000', NULL, 1),
(6052899, 888282, 66515, '<td valign="top">going have to see which Canuck submitted this and where it was taken? My guess is this is somewhere near Maligne Lake in Jasper National Park.</td>', 'going have to see which Canuck submitted this and where it was taken? My guess is this is somewhere near Maligne Lake in Jasper National Park.', '2010-06-12 22:28:57.000000', NULL, 1),
(6053068, 888948, 118503, '<td valign="top">Uh...</td>', 'Uh...', '2010-06-13 01:54:52.000000', NULL, 1),
(6053069, 889258, 118503, '<td valign="top">Try again.</td>', 'Try again.', '2010-06-13 01:55:05.000000', NULL, 1),
(6053125, 888307, 5822, '<td valign="top">My guess is this is the fine work of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=66709" rel="nofollow" target="_blank">Whiterook</a>. If it is, you could have retitled the image Awesome Squirrel. Sorry, don''t see the challenge theme expressed in your photo, (perhaps you interpreted HDR as high death rate?) so I had to drop your score from a 1 to a 2.</td>', 'My guess is this is the fine work of  Whiterook. If it is, you could have retitled the image Awesome Squirrel. Sorry, don''t see the challenge theme expressed in your photo, (perhaps you interpreted HDR as high death rate?) so I had to drop your score from a 1 to a 2.', '2010-06-13 03:32:15.000000', NULL, 1),
(6053133, 889073, 5822, '<td valign="top">Sorry, I really can''t see any HDR processing here. It''s way too dark and the shadows are blocked up. It does have visual interest for me but I see this more as digital art than a photo. Wish I could have given you higher.</td>', 'Sorry, I really can''t see any HDR processing here. It''s way too dark and the shadows are blocked up. It does have visual interest for me but I see this more as digital art than a photo. Wish I could have given you higher.', '2010-06-13 04:08:32.000000', NULL, 1),
(6053137, 889278, 5822, '<td valign="top">While a nice photo with great clarity and good composition, I think it''s going to fall short as an HDR and this may hurt your scoring. The highlights are very good, but the shadows are a bit too deep. Also your non-HDR processing in the foliage is a little too obvious. The biggest negative is the sky has no detail and looks really bad</td>', 'While a nice photo with great clarity and good composition, I think it''s going to fall short as an HDR and this may hurt your scoring. The highlights are very good, but the shadows are a bit too deep. Also your non-HDR processing in the foliage is a little too obvious. The biggest negative is the sky has no detail and looks really bad', '2010-06-13 04:22:44.000000', NULL, 1),
(6053141, 888018, 30861, '<td valign="top">Is this Cynthiann? There''s something about it that seems to suggest her...</td>', 'Is this Cynthiann? There''s something about it that seems to suggest her...', '2010-06-13 04:29:49.000000', NULL, 1),
(6053142, 888147, 30861, '<td valign="top">No, maybe THIS one''s Cynthiann? :-) Maybe I need to stop trying to guess which one is Cynthiann?</td>', 'No, maybe THIS one''s Cynthiann? :-) Maybe I need to stop trying to guess which one is Cynthiann?', '2010-06-13 04:31:08.000000', NULL, 1),
(6053178, 889034, 62357, '<td valign="top">What a coincidence, I was just there last Sunday :)</td>', 'What a coincidence, I was just there last Sunday :)', '2010-06-13 06:13:41.000000', NULL, 1),
(6053184, 889259, 79955, '<td valign="top">Very nice !!! HDR from a single shot is my guess. 8</td>', 'Very nice !!! HDR from a single shot is my guess. 8', '2010-06-13 06:47:30.000000', NULL, 1),
(6053185, 889044, 79955, '<td valign="top">Subject matter a little bland, also the shot is not too crisp. 5</td>', 'Subject matter a little bland, also the shot is not too crisp. 5', '2010-06-13 06:48:43.000000', NULL, 1),
(6053187, 888849, 79955, '<td valign="top">Very much a HDR , very suitable subject matter for a HDR. Very painterly feel to it. 7</td>', 'Very much a HDR , very suitable subject matter for a HDR. Very painterly feel to it. 7', '2010-06-13 06:50:10.000000', NULL, 1),
(6053188, 888778, 79955, '<td valign="top">IMO , the water does not look too attractive or add to the shot.  6</td>', 'IMO , the water does not look too attractive or add to the shot.  6', '2010-06-13 06:52:16.000000', NULL, 1),
(6053189, 888847, 79955, '<td valign="top">Interesting perspective , a tad insufficient DOF to get everything tack sharp. 6</td>', 'Interesting perspective , a tad insufficient DOF to get everything tack sharp. 6', '2010-06-13 06:53:15.000000', NULL, 1),
(6053191, 888191, 79955, '<td valign="top">The resulting image is not crisp enough.  6</td>', 'The resulting image is not crisp enough.  6', '2010-06-13 06:55:28.000000', NULL, 1),
(6053192, 888954, 79955, '<td valign="top">IMO , the green &amp; yellows should have been toned down !!! Too easy to get carried away when creating a HDR image. 6</td>', 'IMO , the green & yellows should have been toned down !!! Too easy to get carried away when creating a HDR image. 6', '2010-06-13 06:58:19.000000', NULL, 1),
(6053193, 889206, 79955, '<td valign="top">Nice perspective , very cleanly composed. Wish it was crisper with more texture on the walls. 7</td>', 'Nice perspective , very cleanly composed. Wish it was crisper with more texture on the walls. 7', '2010-06-13 07:00:22.000000', NULL, 1),
(6053198, 888286, 5822, '<td valign="top">This has got to be the winner. It''s got the clarity, colors, good compositional design (great leading lines), detail in the shadows, yet an image that doesn''t scream HDR and a beautiful sunset to boot. Just lovely! Bumping to a 10.</td>', 'This has got to be the winner. It''s got the clarity, colors, good compositional design (great leading lines), detail in the shadows, yet an image that doesn''t scream HDR and a beautiful sunset to boot. Just lovely! Bumping to a 10.', '2010-06-13 07:05:38.000000', NULL, 1),
(6053199, 888360, 5822, '<td valign="top">Lovely light and beautifully soft pastel colors. A lovely piece. Bumping up to a 9.</td>', 'Lovely light and beautifully soft pastel colors. A lovely piece. Bumping up to a 9.', '2010-06-13 07:05:55.000000', NULL, 1),
(6053201, 889244, 5822, '<td valign="top">Exquisite lighting and colors with a vintage feel that should get you a ribbon. Excellent clarity and detail. Masterful job. I love this!</td>', 'Exquisite lighting and colors with a vintage feel that should get you a ribbon. Excellent clarity and detail. Masterful job. I love this!', '2010-06-13 07:06:30.000000', NULL, 1),
(6053202, 888967, 5822, '<td valign="top">Deep rich browns and greens are just exquisite. Lovely scene, and I love the rushing and still waters. Painterly. This is my favorite for the challenge, though not my highest scoring because it''s not <i>obviously</i> HDR, though I believe it to be, and ironically, this may be its strongest point. Some may think it lacks a human presence (say fly fishing), but I believe it to be perfect as is. A timeless classic. Take a bow.</td>', 'Deep rich browns and greens are just exquisite. Lovely scene, and I love the rushing and still waters. Painterly. This is my favorite for the challenge, though not my highest scoring because it''s not obviously HDR, though I believe it to be, and ironically, this may be its strongest point. Some may think it lacks a human presence (say fly fishing), but I believe it to be perfect as is. A timeless classic. Take a bow.', '2010-06-13 07:07:18.000000', NULL, 1),
(6053203, 888820, 5822, '<td valign="top">Reminds me of crop circles. Colors are beautiful and I like the composition very much, though I would have liked to have seen the tops of those distant hills. I find the image a bit soft, but I don''t think that needs improvement. Gives it an abstract quality. Also, I think it would benefit from a border. Very well done. Bumping up to an 8.</td>', 'Reminds me of crop circles. Colors are beautiful and I like the composition very much, though I would have liked to have seen the tops of those distant hills. I find the image a bit soft, but I don''t think that needs improvement. Gives it an abstract quality. Also, I think it would benefit from a border. Very well done. Bumping up to an 8.', '2010-06-13 07:08:02.000000', NULL, 1),
(6053204, 887234, 5822, '<td valign="top">A masterful job, Fred. Those clouds are just amazing.</td>', 'A masterful job, Fred. Those clouds are just amazing.', '2010-06-13 07:08:10.000000', NULL, 1),
(6053207, 888961, 5822, '<td valign="top">A beautiful and bold and unique statement. Starburst and flare powerful and really well done. Colors are rich and the flower petals you''ve captured in perfect form. A blue or red for you. Bumping up to a 10</td>', 'A beautiful and bold and unique statement. Starburst and flare powerful and really well done. Colors are rich and the flower petals you''ve captured in perfect form. A blue or red for you. Bumping up to a 10', '2010-06-13 07:12:19.000000', NULL, 1),
(6053208, 889193, 5822, '<td valign="top">A very nice sharp and detailed vista with beautiful coloring that''s quite attractive and meets the challenge theme very well. A couple of things I''m not fond of are what looks like phony (dodged?) highlighted foliage in the foreground, and the centered horizon with too much sky.</td>', 'A very nice sharp and detailed vista with beautiful coloring that''s quite attractive and meets the challenge theme very well. A couple of things I''m not fond of are what looks like phony (dodged?) highlighted foliage in the foreground, and the centered horizon with too much sky.', '2010-06-13 07:12:55.000000', NULL, 1),
(6053209, 888018, 5822, '<td valign="top">Excellent perspective and composition. Attractively ugly. Lovely muted colors. Well lit. I can see this as part of a series on dilapidated and abandoned homes. Well done.</td>', 'Excellent perspective and composition. Attractively ugly. Lovely muted colors. Well lit. I can see this as part of a series on dilapidated and abandoned homes. Well done.', '2010-06-13 07:13:20.000000', NULL, 1),
(6053210, 887876, 5822, '<td valign="top">Though I believe this image will score well, it should be analogous to a two headed histogram. Some voters will hate it for its rustic, grungy, and inelegant qualities, and others will love it for its colors, compositional elements, and abstractness. I''m tending towards the latter group also for its uniqueness but believe it to be too bright.</td>', 'Though I believe this image will score well, it should be analogous to a two headed histogram. Some voters will hate it for its rustic, grungy, and inelegant qualities, and others will love it for its colors, compositional elements, and abstractness. I''m tending towards the latter group also for its uniqueness but believe it to be too bright.', '2010-06-13 07:13:55.000000', NULL, 1),
(6053214, 889274, 5822, '<td valign="top">Excellent DOF that has a three dimensional quality. Lovely muted colors as well but lacks the wow factor to be up in contention.</td>', 'Excellent DOF that has a three dimensional quality. Lovely muted colors as well but lacks the wow factor to be up in contention.', '2010-06-13 07:16:52.000000', NULL, 1),
(6053215, 888116, 5822, '<td valign="top">Very Edward Westonish in tonal quality though lacks compositional interest for me.</td>', 'Very Edward Westonish in tonal quality though lacks compositional interest for me.', '2010-06-13 07:20:30.000000', NULL, 1),
(6053216, 888849, 5822, '<td valign="top">Nice nostalgic piece with great pastel colors. My major complaints would be too tight a crop; sky''s been dodged and burned a bit too much; electrical wires at top right could have been cloned out; and the border is barely noticeable. That last point may go over big with those who don''t like them though. Also, I''m guessing you used a GND as the sky appears to have a magenta cast and doesn''t seem to match the other parts of the photo regarding color or lighting.</td>', 'Nice nostalgic piece with great pastel colors. My major complaints would be too tight a crop; sky''s been dodged and burned a bit too much; electrical wires at top right could have been cloned out; and the border is barely noticeable. That last point may go over big with those who don''t like them though. Also, I''m guessing you used a GND as the sky appears to have a magenta cast and doesn''t seem to match the other parts of the photo regarding color or lighting.', '2010-06-13 07:21:47.000000', NULL, 1),
(6053217, 887973, 5822, '<td valign="top">I''m not getting this photo. What''s the connection of your beautiful model to this dump? I hope you took her out for a nice dinner and maybe even bought her a gift for standing there.</td>', 'I''m not getting this photo. What''s the connection of your beautiful model to this dump? I hope you took her out for a nice dinner and maybe even bought her a gift for standing there.', '2010-06-13 07:28:34.000000', NULL, 1),
(6053218, 889279, 5822, '<td valign="top">Your subjects are too small to have any meaningful impact and my eyes hurt trying to see what they''re doing.</td>', 'Your subjects are too small to have any meaningful impact and my eyes hurt trying to see what they''re doing.', '2010-06-13 07:31:28.000000', NULL, 1),
(6053219, 888201, 5822, '<td valign="top">The aerial perspective and DOF is wonderful and I like the rhythm in your title and photograph along with its implied leading line. I find my eye skips along from red skiff to blue then to geese but this compositional element itself is not enough to prevent the image from losing some of its poetry for me. The mood is ambivalent. Colors go from bold to muted, grass  too yellow a green, yet sky too drab a purple. The sky appears flat lacking any detail. It looks as though you''ve used a GND (maybe too strong a one). My guess is you over processed the overall image to make up for the flat available light. <br/> <br/>Also, whatever is sticking up out of the red skiff is distracting. One other nitpick is the positioning of the blue skiff. I know you have no control over this matter, but I wish it were facing towards the tree so that we could see more of its port side to serve a better foil to the red boat. Finally, the pink lifesaver is the straw for the camel and really does this image in, though I think a lot of the voters will like it and vote it highly.</td>', 'The aerial perspective and DOF is wonderful and I like the rhythm in your title and photograph along with its implied leading line. I find my eye skips along from red skiff to blue then to geese but this compositional element itself is not enough to prevent the image from losing some of its poetry for me. The mood is ambivalent. Colors go from bold to muted, grass  too yellow a green, yet sky too drab a purple. The sky appears flat lacking any detail. It looks as though you''ve used a GND (maybe too strong a one). My guess is you over processed the overall image to make up for the flat available light.  Also, whatever is sticking up out of the red skiff is distracting. One other nitpick is the positioning of the blue skiff. I know you have no control over this matter, but I wish it were facing towards the tree so that we could see more of its port side to serve a better foil to the red boat. Finally, the pink lifesaver is the straw for the camel and really does this image in, though I think a lot of the voters will like it and vote it highly.', '2010-06-13 07:34:21.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6053220, 888210, 5822, '<td valign="top">Green is too hot and vista needs more variational forms in the foreground to be of interest. The detail there is lacking from what looks like plugged shadows. I also find the sky too grainy with unreal colors.</td>', 'Green is too hot and vista needs more variational forms in the foreground to be of interest. The detail there is lacking from what looks like plugged shadows. I also find the sky too grainy with unreal colors.', '2010-06-13 07:38:19.000000', NULL, 1),
(6053222, 889259, 5822, '<td valign="top">Nice capture but composition a bit static and colors a little noisy. Not really seeing the HDR qualities most would be looking for in this challenge.</td>', 'Nice capture but composition a bit static and colors a little noisy. Not really seeing the HDR qualities most would be looking for in this challenge.', '2010-06-13 07:40:49.000000', NULL, 1),
(6053224, 888376, 5822, '<td valign="top">Spooky.</td>', 'Spooky.', '2010-06-13 07:47:51.000000', NULL, 1),
(6053239, 889274, 107976, '<td valign="top">Mind blowing. I am biased</td>', 'Mind blowing. I am biased', '2010-06-13 08:53:35.000000', NULL, 1),
(6053291, 889037, 108069, '<td valign="top">Well this is a stunning shot. Incredible. The only flaw I can point out is that I don''t live near there. Excellent.</td>', 'Well this is a stunning shot. Incredible. The only flaw I can point out is that I don''t live near there. Excellent.', '2010-06-13 10:28:13.000000', NULL, 1),
(6053295, 888090, 108069, '<td valign="top">I really like this. It''s a bit different, which is good. Great tones, cool color. Nice work.</td>', 'I really like this. It''s a bit different, which is good. Great tones, cool color. Nice work.', '2010-06-13 10:30:13.000000', NULL, 1),
(6053592, 888975, 104537, '<td valign="top">Gorgeous!! The depth of the shadows in contrast with the amber glow of the lights is wonderful!</td>', 'Gorgeous!! The depth of the shadows in contrast with the amber glow of the lights is wonderful!', '2010-06-13 17:44:05.000000', NULL, 1),
(6053594, 888970, 104537, '<td valign="top">WOW this is amazing! Wonderful effect. Love it!</td>', 'WOW this is amazing! Wonderful effect. Love it!', '2010-06-13 17:44:49.000000', NULL, 1),
(6053596, 888968, 104537, '<td valign="top">Such a moving and expressive image. The old house whispers a story of the past. Excellent capture.</td>', 'Such a moving and expressive image. The old house whispers a story of the past. Excellent capture.', '2010-06-13 17:45:52.000000', NULL, 1),
(6053597, 888980, 104537, '<td valign="top">Very dramatic image. Great tones and depth.</td>', 'Very dramatic image. Great tones and depth.', '2010-06-13 17:51:34.000000', NULL, 1),
(6053601, 888210, 104537, '<td valign="top">Very nice! The overall landscape is amazing, love the mountains as the backdrop, very effective.</td>', 'Very nice! The overall landscape is amazing, love the mountains as the backdrop, very effective.', '2010-06-13 17:52:35.000000', NULL, 1),
(6053603, 889071, 104537, '<td valign="top">Perfect timing, the rainbow adds a sense of serenity to the overall image. Love it!</td>', 'Perfect timing, the rainbow adds a sense of serenity to the overall image. Love it!', '2010-06-13 17:53:28.000000', NULL, 1),
(6053605, 889073, 104537, '<td valign="top">Nice!! Such warm tones, you really captured the depth of the leaves and stem in this one, 3D...wonderful capture!</td>', 'Nice!! Such warm tones, you really captured the depth of the leaves and stem in this one, 3D...wonderful capture!', '2010-06-13 17:54:38.000000', NULL, 1),
(6053607, 888794, 104537, '<td valign="top">Such an amazing face. Great capture</td>', 'Such an amazing face. Great capture', '2010-06-13 17:55:13.000000', NULL, 1),
