(6054546, 889086, 118315, '<td valign="top">Try cropping this shot with just a thin ribbon of sky and removing some of the foreground.  Some of the right could go as well.</td>', 'Try cropping this shot with just a thin ribbon of sky and removing some of the foreground.  Some of the right could go as well.', '2010-06-13 23:38:46.000000', NULL, 1),
(6054547, 888794, 118315, '<td valign="top">Very well done.</td>', 'Very well done.', '2010-06-13 23:38:52.000000', NULL, 1),
(6054548, 888201, 118315, '<td valign="top">I would crop about half of the tree on the left side.  Cropping is tough, we never want to eliminate some nice details but everything needs to serve the composition as a whole.</td>', 'I would crop about half of the tree on the left side.  Cropping is tough, we never want to eliminate some nice details but everything needs to serve the composition as a whole.', '2010-06-13 23:39:04.000000', NULL, 1),
