(6054756, 888307, 100831, '<td valign="top">oh.... poor thing. Well at least you made him look pretty.</td>', 'oh.... poor thing. Well at least you made him look pretty.', '2010-06-14 01:06:22.000000', NULL, 0),
(6054757, 888142, 39057, '<td valign="top">Nice finish.</td>', 'Nice finish.', '2010-06-14 01:06:36.000000', NULL, 0),
(6054758, 889073, 83313, '<td valign="top">Glad to see this was appreciated by others, and pleased to find out whose it is. Well deserving of the HM!</td>', 'Glad to see this was appreciated by others, and pleased to find out whose it is. Well deserving of the HM!', '2010-06-14 01:06:41.000000', NULL, 0),
(6054759, 888326, 30982, '<td valign="top">A heaping dose of WOW.  Nice work!</td>', 'A heaping dose of WOW.  Nice work!', '2010-06-14 01:06:46.000000', NULL, 0),
(6054761, 888286, 67697, '<td valign="top">That sky is amazing, Andrew.  Congrats on the blue!</td>', 'That sky is amazing, Andrew.  Congrats on the blue!', '2010-06-14 01:07:01.000000', NULL, 0),
(6054762, 888201, 27164, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Yo_Spiff:</b></div><hr/><i> Thought this could be yours.</i></td></tr></table> <br/>I think any entry with the word "Skiff" in the title is a dead giveaway. :)</td>', 'Originally posted by Yo_Spiff: Thought this could be yours. I think any entry with the word "Skiff" in the title is a dead giveaway. :)', '2010-06-14 01:07:12.000000', NULL, 0),
(6054763, 888286, 118315, '<td valign="top">It is a setting sun picture.  The saturation works just fine.</td>', 'It is a setting sun picture.  The saturation works just fine.', '2010-06-14 01:07:21.000000', NULL, 0),
(6054764, 888142, 83313, '<td valign="top">Top 10. Whoo-Hooo! Way to go!</td>', 'Top 10. Whoo-Hooo! Way to go!', '2010-06-14 01:07:27.000000', NULL, 0),
(6054766, 888286, 40718, '<td valign="top">Great colors!  Congrats on the blue!</td>', 'Great colors!  Congrats on the blue!', '2010-06-14 01:07:50.000000', NULL, 0),
(6054768, 889037, 40718, '<td valign="top">You definitely know your way around a seascape.  Where is this?</td>', 'You definitely know your way around a seascape.  Where is this?', '2010-06-14 01:08:31.000000', NULL, 0),
(6054769, 889216, 30982, '<td valign="top">Beautifully tonemapped, though having seen the orignals, you also had the sense to shoot a beautifully lit and well composed scene.  Congrats on the 6+ and decent placing, too.</td>', 'Beautifully tonemapped, though having seen the orignals, you also had the sense to shoot a beautifully lit and well composed scene.  Congrats on the 6+ and decent placing, too.', '2010-06-14 01:08:34.000000', NULL, 0),
(6054771, 888201, 40718, '<td valign="top">Well, congrats on the green.   Too bad we couldn''t both have been on the front page together.  Let''s go bum rush william88!!!</td>', 'Well, congrats on the green.   Too bad we couldn''t both have been on the front page together.  Let''s go bum rush william88!!!', '2010-06-14 01:09:24.000000', NULL, 0),
(6054775, 888201, 12253, '<td valign="top">Gorgeous shot, congratulations on 4th!</td>', 'Gorgeous shot, congratulations on 4th!', '2010-06-14 01:09:53.000000', NULL, 0),
(6054776, 889214, 66515, '<td valign="top">I personally thought that this was an excellent use for HDR. Normally the background outside would be blown out. In this case you''ve retained detail out. It would be nice the shadows were a little brighter and the window frame was squared up (darn lens distortion!)</td>', 'I personally thought that this was an excellent use for HDR. Normally the background outside would be blown out. In this case you''ve retained detail out. It would be nice the shadows were a little brighter and the window frame was squared up (darn lens distortion!)', '2010-06-14 01:10:01.000000', NULL, 0),
(6054777, 888778, 83313, '<td valign="top">A 6+ in a tough challenge. Thanks for the explanation of the title.</td>', 'A 6+ in a tough challenge. Thanks for the explanation of the title.', '2010-06-14 01:10:17.000000', NULL, 0),
(6054778, 888778, 30982, '<td valign="top">Nice job!  Congrats on the 6+ score with this, too.</td>', 'Nice job!  Congrats on the 6+ score with this, too.', '2010-06-14 01:10:29.000000', NULL, 0),
