(6057435, 889073, 74979, '<td valign="top">so happy one of the Top 5 though IMO, should''ve been a ribbon winner<br/> <br/>ahh well...Congrats!!<br/></td>', 'so happy one of the Top 5 though IMO, should''ve been a ribbon winner ahh well...Congrats!!', '2010-06-15 21:30:43.000000', NULL, 0),
(6057483, 889034, 74979, '<td valign="top">God, this is SO UNDERRATED!! I gave this an 8..perhaps b/c I love that bridge..but you handled this difficult lighting and composition so well IMO Deb!<br/></td>', 'God, this is SO UNDERRATED!! I gave this an 8..perhaps b/c I love that bridge..but you handled this difficult lighting and composition so well IMO Deb!', '2010-06-15 22:05:52.000000', NULL, 0),
